// Generated by scripts/gen_contract.mjs from packages/contract/schema-graph.v1.json. Do not edit by hand.
// Run `npm run contract` after changing the schema; `npm run contract:check` fails on drift.
//
// These interfaces describe a SchemaGraph after normalize() has run: the schema accepts the
// legacy boolean and nullable wire forms, normalize() coerces them, and only the coerced
// document reaches a view. Unknown fields are kept as data, which is why SchemaGraph,
// SchemaTable, SchemaSource and the profiling types carry an index signature.

export const CONTRACT_VERSION = '1.0';

// The exchange format adapters emit and the artifact renders. It is an exchange format, not a claim that every
// database uses the same type system.
export interface SchemaGraph {
  // Contract version as MAJOR.MINOR. A document without the field is treated as 1.0. A different major version
  // is rejected; a higher minor version is accepted and its unknown fields are ignored.
  contractVersion?: string;
  // Project identity.
  project?: SchemaProject;
  // Evidence provenance.
  source?: SchemaSource;
  // Every table and view in the selected scope, with unique ids.
  tables: SchemaTable[];
  // Every relationship, one entry per ordered column pair.
  links: SchemaLink[];
  [key: string]: unknown;
}

// Identity of the schema under review. The key scopes browser storage and review decisions and must stay
// stable for one project environment. See C13.
export interface SchemaProject {
  // Human-readable project name. Rendered escaped in the header, the provenance footer and the artifact title.
  name: string;
  // Stable lowercase key, matching the character set normalize() enforces. Two environments with identical
  // table names must not share a key.
  key: string;
  // SQL dialect of the source. Defaults to unknown, which turns generated SQL off. Generated SQL is supported
  // for postgresql and sqlite only, and is always a draft the product never executes. See C04.
  dialect: string;
}

// Where the graph came from and how far its evidence reaches. normalize() supplies a default for every field
// so the provenance footer is never blank; adapters should still emit the real values. See C09.
export interface SchemaSource {
  // Path or identifier of the evidence source.
  file?: string;
  // Verified reference or snapshot id. The provenance footer shows its first eight characters.
  commit?: string;
  // Hash of the source bytes, or a recorded placeholder.
  sha256?: string;
  // When the graph was produced.
  generated?: string;
  // What the evidence covers and what it does not. Shown as the provenance tooltip. See C09.
  basis?: string;
  [key: string]: unknown;
}

// One entity of the graph. Additional catalog metadata is kept as data and passed through unchanged.
export interface SchemaTable {
  // Unique lookup id for the table. It may contain dots; identifiers are never split on dots for SQL
  // generation.
  id: string;
  // Physical table name, supplied separately from the display id.
  name?: string;
  // Physical schema name.
  schema?: string;
  // Application or ORM class name for this entity.
  className: string;
  // Declared domain, or a discovered community label. A discovered community is an analytical suggestion. See
  // C03.
  domain: string;
  // Entity category. The visual uses Core master entity, Transaction / operational, Association / detail,
  // Configuration / reference and Audit / integration state; custom labels are allowed and Unclassified is
  // used when evidence is insufficient.
  type: string;
  // Whether the entity is a base table or a view. Defaults to table. View metadata never supplies executable
  // SQL. See C04.
  kind?: 'table' | 'view';
  // View or entity definition text. Display-only and never executed. See C04.
  definition?: string;
  // Evidence file for this table, when it differs from the graph source.
  file?: string;
  // Line in the evidence file. A non-negative integer; a string is rejected.
  line?: number;
  // Primary-key column names joined for display. normalize() derives it from primaryKey or from the
  // primary-key flags.
  pk: string;
  // Ordered primary-key column names. When present it takes precedence over the per-column flags and preserves
  // a composite key's declared order.
  primaryKey?: string[];
  // Every column of the entity, with unique non-empty names.
  allColumns: SchemaColumn[];
  // Index groups.
  indexes: SchemaIndex[];
  // Unique groups, including single-column constraints. See C06.
  uniques: SchemaIndex[];
  // Check constraints.
  checks?: SchemaCheck[];
  // Exact row count from the adapter or from an exhausted sample, or null when unknown. Zero is a measured
  // value and is never substituted for unknown. See C01.
  rowCount?: number | null;
  // Lower bound from a capped sample. A capped sample yields a lower bound, not a total, and it is present
  // only while rowCount is unknown. See C01.
  rowCountLowerBound?: number;
  // Whether rowCount is exact rather than a floor.
  rowCountExact?: boolean;
  // Rows examined for this table by the last profiling run.
  sampleSize?: number;
  // True when the last profiling run sampled this table.
  sampled?: boolean;
  // Table-level profiling metadata, including completeness.
  profiling?: TableProfiling;
  [key: string]: unknown;
}

// One ordered column pair. A composite foreign key is emitted as one link per pair, all sharing a non-empty
// constraintId, and counts once as a relationship while the association count is column pairs. See C11.
export interface SchemaLink {
  // Child table id. It must exist in tables.
  source: string;
  // Child column name. It must exist in the source table.
  column: string;
  // Parent table id. A declared target must resolve in the loaded scope; an inferred target may be absent and
  // is then labelled unresolved.
  target: string;
  // Parent column name.
  targetColumn: string;
  // Evidence class, exactly one of the two values. A declared relationship comes from whatever evidence source
  // the snapshot identifies; a naming-based one is an observation about column names. The two classes stay
  // distinguishable in data, styling and labels. See C07 and C09.
  kind: 'declared FK' | 'inferred by naming';
  // Constraint identity, non-empty and unique within the source table. Every pair of one composite foreign key
  // shares it. See C11.
  constraintId?: string;
  // Display name for the relationship.
  name?: string;
  // Referential action recorded for the relationship.
  ondelete?: string;
  // Cardinality when the evidence establishes it, otherwise unknown.
  cardinality?: 'one-to-many' | 'one-to-one' | 'unknown';
}

// One column of a table. Only name is required on the wire; normalize() supplies the defaults the views rely
// on, so the generated TypeScript type describes the normalized document.
export interface SchemaColumn {
  // Physical column name, unique within its table.
  name: string;
  // Declared type as written in the evidence source. An unknown type stays Unknown rather than being guessed.
  type: string;
  // Primary-key membership flag. An explicit primaryKey array on the table takes precedence. A column named id
  // is not a primary key without evidence.
  pk: boolean;
  // Display-only foreign-key target text. Actual relationships come from links; a link is never invented from
  // this text. See C07.
  fk: string;
  // Tri-state nullability: an empty string means unknown, otherwise True or False. Booleans and the legacy
  // string forms are accepted on the wire and coerced by normalize().
  nullable: '' | 'True' | 'False';
  // Whether the column carries a single-column index. Partial and expression indexes are excluded from
  // coverage heuristics.
  index: boolean;
  // Whether the column carries a unique constraint of its own. Membership in a composite unique group is a
  // different fact and is not this flag. See C06.
  unique: boolean;
  // Evidence file for this column, when it differs from the graph source.
  file?: string;
  // Line in the evidence file. A non-negative integer; a string is rejected.
  line?: number;
  // How the type was established, for example a catalog read or an ORM model.
  typeBasis?: string;
  // Full type definition text, for example an enumeration body.
  typeDefinition?: string;
  // Default as recorded by the adapter, without a claim about where it is applied.
  default?: unknown;
  // Default the database applies. See C15.
  serverDefault?: unknown;
  // Default the application applies. It is not a SQL default and does not constrain rows written by other
  // clients. See C15.
  applicationDefault?: unknown;
  // Referential action recorded for this column's declared relationship.
  ondelete?: string;
  // Bounded sample statistics for this column.
  profiling?: ColumnProfiling;
  // At most three distinct, non-NULL, bounded scalars, written at the column level by the profiler when the
  // caller opted in.
  sampleValues?: unknown[];
}

// An ordered column group. Column-level unique constraints appear as single-column groups; ordered composite
// groups stay intact.
export interface SchemaIndex {
  // Constraint or index name.
  name?: string;
  // Ordered column names. Every name must exist in allColumns unless the group is an expression index.
  columns: string[];
  // Whether the group enforces uniqueness.
  unique?: boolean;
  // Whether the index is partial or filtered. Partial indexes are removed from generic full-coverage
  // heuristics.
  partial?: boolean;
  // Whether the index is over expressions rather than plain columns. Expression indexes are removed from
  // generic full-coverage heuristics.
  expression?: boolean;
}

// A named check constraint. The definition is display-only and is never executed. See C04.
export interface SchemaCheck {
  // Constraint name.
  name?: string;
  // Constraint body as written in the evidence source.
  definition?: string;
}

// Metadata about the profiling run for one table, including its completeness. An incomplete table keeps
// whatever statistics were gathered; everything else stays unknown. See C01 and C05.
export interface TableProfiling {
  // Whether the profiling run finished for this table. An incomplete table is labelled, never back-filled with
  // zeros. See C01 and C05.
  status?: 'complete' | 'incomplete';
  // Why the run is incomplete, in fixed wording chosen by the worker.
  reason?: string;
  // Rows examined for this table.
  sampleSize?: number;
  // True when the metadata comes from a sample rather than the whole table.
  sampled?: boolean;
  // Scope label for the metadata.
  scope?: string;
  [key: string]: unknown;
}

// Per-column observations from an explicitly requested, read-only, capped sample. Absent fields are unknown,
// never zero. See C01 and C05.
export interface ColumnProfiling {
  // Observed fraction of NULL values in the sample, or null when the sample was empty.
  nullFraction?: number;
  // Distinct non-NULL values observed in the sample. A sample distinct count is not a database uniqueness
  // guarantee. See C05.
  distinctCount?: number;
  // Smallest value observed in the sample, as a bounded scalar. Extremes can be sensitive and are never
  // published implicitly.
  min?: unknown;
  // Largest value observed in the sample, as a bounded scalar.
  max?: unknown;
  // Rows examined for this column.
  sampleSize?: number;
  // True when the statistics come from a sample rather than the whole table. See C05.
  sampled?: boolean;
  // Scope label for the statistics, for example sampled or table.
  scope?: string;
  // At most three distinct, non-NULL, bounded scalars, retained only when the caller opted in. Exports strip
  // them unless the exporter opts in as well.
  sampleValues?: unknown[];
}
